#!/bin/sh
# om-prepare-test-env: generated entrypoint (contract v2)
# regenerate with: om-prepare-test-env --regenerate
# history:
#   2026-09-06 generated by hand from scripts/agent/setup-e2e.sh (cold ~90s after bootstrap, warm ~1s)
set -eu

# ── Project variables ────────────────────────────────────────────────────────
# Provisioning (deps, .dev.vars, local D1 + airports, basemap) is owned by
# scripts/worktree/bootstrap.sh and is a precondition here, never repeated.
BOOTSTRAP="scripts/worktree/bootstrap.sh"
# 3030-3040 is the only range playwright.config.ts accepts outside CI, so an
# automated run can never photograph another checkout's app.
PORT_MIN=3030
PORT_MAX=3040
HOST=127.0.0.1                # v4 only: another checkout may sit on [::1]
HEALTH_PATH=/
HEALTH_TIMEOUT=120            # seconds
SEED_CMD="node scripts/seed/seed.mjs --url"
VERIFY_CMD="node scripts/seed/verify.mjs"
DEMO_EMAIL="rafal@planned.travel"     # scripts/seed/seed.mjs admin, e2e/helpers/session.ts DEMO_EMAIL
DEMO_PASSWORD="planned-demo-2026"   # scripts/seed/seed.mjs DEFAULT_DEMO_PASSWORD, demo-grade
TTL="${TEST_ENV_CACHE_TTL_SECONDS:-600}"

QA_DIR=".ai/qa"
DESCRIPTOR="$QA_DIR/test-env.json"
CREDS_FILE="$QA_DIR/test-env.env"
LOCK_DIR="$QA_DIR/test-env.lock"
PID_FILE="$QA_DIR/dev-server.pid"
LOG_FILE="dev-server.log"

FORCE=0
for arg in "$@"; do
  case "$arg" in
    --force) FORCE=1 ;;
    --force-rebuild) FORCE=1 ;;   # no build cache: the dev server compiles on demand
    *) echo "unknown flag: $arg" >&2; exit 2 ;;
  esac
done

cd "$(git rev-parse --show-toplevel)"
mkdir -p "$QA_DIR"

# ── Lock ─────────────────────────────────────────────────────────────────────
release_lock() { rm -rf "$LOCK_DIR"; }
acquire_lock() {
  i=0
  while ! mkdir "$LOCK_DIR" 2>/dev/null; do
    owner=$(sed -n 's/.*"pid": *\([0-9]*\).*/\1/p' "$LOCK_DIR/owner.json" 2>/dev/null || true)
    if [ -n "$owner" ] && ! kill -0 "$owner" 2>/dev/null; then
      rm -rf "$LOCK_DIR"; continue
    fi
    i=$((i + 1)); [ "$i" -gt 150 ] && { echo "ERROR: test-env lock held by pid ${owner:-?} for 5 min" >&2; exit 1; }
    sleep 2
  done
  printf '{"pid": %s, "source": "test-env-up.sh", "acquiredAt": "%s"}\n' "$$" "$(date -u +%FT%TZ)" > "$LOCK_DIR/owner.json"
  trap release_lock EXIT INT TERM
}
acquire_lock

# ── Helpers ──────────────────────────────────────────────────────────────────
port_busy() { (exec 3<>"/dev/tcp/$HOST/$1") >/dev/null 2>&1; }
healthy() { curl -sf -o /dev/null --max-time 5 "$1$HEALTH_PATH"; }
json_field() { sed -n "s/.*\"$1\": *\"\{0,1\}\([^\",}]*\)\"\{0,1\}.*/\1/p" "$DESCRIPTOR" 2>/dev/null | head -1; }
epoch() { date +%s; }

emit_result() {
  echo "TEST_ENV_STATUS=running"
  echo "TEST_ENV_BASE_URL=$1"
  echo "TEST_ENV_DESCRIPTOR=$DESCRIPTOR"
  echo "TEST_ENV_REUSED=$2"
  echo "BROWSER_PROVIDER=playwright"
  echo "BROWSER_INSTALLED=1"
}

# ── Reuse check ──────────────────────────────────────────────────────────────
if [ "$FORCE" = 0 ] && [ -f "$DESCRIPTOR" ] && [ "$(json_field status)" = "running" ]; then
  OLD_PID=$(json_field pid)
  OLD_URL=$(json_field baseUrl)
  OLD_STARTED=$(json_field startedAt)
  fresh=1
  if [ -n "$OLD_STARTED" ]; then
    started_epoch=$(date -u -j -f '%Y-%m-%dT%H:%M:%SZ' "$OLD_STARTED" +%s 2>/dev/null || date -u -d "$OLD_STARTED" +%s 2>/dev/null || echo 0)
    [ $(( $(epoch) - started_epoch )) -gt "$TTL" ] && fresh=0
    # A tracked source newer than the boot means the running server may be stale
    # for SSR-only modules; vite reloads most of it, so this is a TTL-style hint.
    if [ "$fresh" = 1 ] && [ -n "$(git ls-files -m -- src server 2>/dev/null | head -1)" ]; then
      newest=$(git ls-files -m -z -- src 2>/dev/null | xargs -0 stat -f %m 2>/dev/null | sort -n | tail -1 || echo 0)
      [ "${newest:-0}" -gt "$started_epoch" ] && fresh=0
    fi
  fi
  if [ -n "$OLD_PID" ] && kill -0 "$OLD_PID" 2>/dev/null && [ -n "$OLD_URL" ] && healthy "$OLD_URL" && [ "$fresh" = 1 ]; then
    emit_result "$OLD_URL" 1
    exit 0
  fi
  # Stale: stop what this repo started, then fall through to a fresh boot.
  [ -n "$OLD_PID" ] && kill "$OLD_PID" 2>/dev/null || true
fi

# ── Precondition: provisioned checkout ───────────────────────────────────────
if ! bash "$BOOTSTRAP" --check >/dev/null 2>&1; then
  echo "==> checkout not provisioned; running $BOOTSTRAP --profile worktree --no-seed"
  bash "$BOOTSTRAP" --profile worktree --no-seed
fi

# ── Port ─────────────────────────────────────────────────────────────────────
PORT=
p=$PORT_MIN
while [ "$p" -le "$PORT_MAX" ]; do
  if ! port_busy "$p"; then PORT=$p; break; fi
  p=$((p + 1))
done
[ -n "$PORT" ] || { echo "ERROR: no free port in $PORT_MIN-$PORT_MAX" >&2; exit 1; }
BASE_URL="http://$HOST:$PORT"

# ── App start + health wait ──────────────────────────────────────────────────
# E2E=1 turns the devtools console relay off in vite.config.ts (a Worker
# console.error would otherwise land in whichever page Playwright has open).
# 4 GB heap: an SSR dev server driven by four browsers for twenty minutes runs
# the default out (issue #117).
echo "==> dev server on :$PORT"
E2E=1 NODE_OPTIONS="${NODE_OPTIONS:-} --max-old-space-size=4096" \
  nohup pnpm exec vite dev --port "$PORT" --strictPort --host "$HOST" > "$LOG_FILE" 2>&1 &
APP_PID=$!
echo "$APP_PID" > "$PID_FILE"

i=0
until healthy "$BASE_URL"; do
  if ! kill -0 "$APP_PID" 2>/dev/null; then
    echo "ERROR: dev server exited before answering on :$PORT" >&2; tail -50 "$LOG_FILE" >&2; exit 1
  fi
  i=$((i + 2)); [ "$i" -ge "$HEALTH_TIMEOUT" ] && { echo "ERROR: no answer on :$PORT within ${HEALTH_TIMEOUT}s" >&2; tail -50 "$LOG_FILE" >&2; exit 1; }
  sleep 2
done

# ── Seed ─────────────────────────────────────────────────────────────────────
echo "==> seeding the demo workspace"
$SEED_CMD "$BASE_URL"
$VERIFY_CMD

# ── Descriptor + credentials ─────────────────────────────────────────────────
RUN_ID="$(date -u +%Y%m%d%H%M%S)-$$"
PLATFORM=$(uname -s | tr '[:upper:]' '[:lower:]'); case "$PLATFORM" in linux*) PLATFORM=linux ;; darwin*) PLATFORM=darwin ;; esac
umask 077
printf 'TEST_DEMO_PASSWORD=%s\n' "$DEMO_PASSWORD" > "$CREDS_FILE"
umask 022
grep -qxF "$CREDS_FILE" .gitignore || echo "$CREDS_FILE" >> .gitignore

cat > "$DESCRIPTOR" <<JSON
{
  "version": 1,
  "runId": "$RUN_ID",
  "status": "running",
  "mode": "dev",
  "baseUrl": "$BASE_URL",
  "startedByThisRepo": true,
  "startScript": ".ai/scripts/test-env-up.sh",
  "stopScript": ".ai/scripts/test-env-down.sh",
  "app": { "startCommand": "pnpm exec vite dev --port $PORT --strictPort --host $HOST", "port": $PORT, "healthPath": "$HEALTH_PATH", "pid": $APP_PID },
  "services": [],
  "credentials": [ { "role": "demo", "username": "$DEMO_EMAIL", "passwordEnv": "TEST_DEMO_PASSWORD" } ],
  "credentialsFile": "$CREDS_FILE",
  "browser": { "provider": "playwright", "installed": true, "command": "pnpm exec playwright", "version": "$(pnpm exec playwright --version 2>/dev/null | sed 's/^Version //')", "descriptor": ".ai/browsers/playwright.md", "notes": "" },
  "playwright": { "runner": "playwright", "installed": true, "config": "playwright.config.ts", "browsers": ["chromium"] },
  "testRunner": { "name": "playwright", "config": "playwright.config.ts" },
  "platform": "$PLATFORM",
  "startedAt": "$(date -u +%FT%TZ)",
  "notes": "Local D1/KV/R2 via Miniflare (.wrangler/). Demo workspace seeded by scripts/seed/seed.mjs; sign in with the demo credential reference. Run the committed suite with: PLAYWRIGHT_BASE_URL=$BASE_URL pnpm e2e. Teardown: sh .ai/scripts/test-env-down.sh"
}
JSON

emit_result "$BASE_URL" 0
